import { Route, Routes } from "react-router-dom";
import Navbar from "./components/Navbar";
import About from "./components/About";
import "./App.css";
import { useEffect, useState } from "react";
import axios from "axios";

function App() {
  // Students state
  const [students, setStudents] = useState([]);

  // Form states
  const [id, setID] = useState("");
  const [Fname, setFname] = useState("");
  const [Lname, setLname] = useState("");
  const [Phone, setPhone] = useState("");
  const [Address, setAddress] = useState("");

  // Alert states
  const [isLoading, setIsLoading] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const [isError, setIsError] = useState(false);
  const [successMessage, setSuccessMessage] = useState(false);
  const [errorMessage, setErrorMessage] = useState(false);

  // Auto-clear success alert after 2.5 seconds
  useEffect(() => {
    if (!isSuccess) return;

    const timer = setTimeout(() => {
      clearAlerts();
    }, 2500);

    return () => clearTimeout(timer);
  }, [isSuccess]);

  // clear errors and success messages
  const clearAlerts = () => {
    setIsSuccess(false);
    setIsError(false);
    setSuccessMessage("");
    setErrorMessage("");
  };

  // show success message
  const showSuccess = (message) => {
    clearAlerts();
    setSuccessMessage(message);
    setIsSuccess(true);
  };

  // show error message
  const showError = (message) => {
    clearAlerts();
    setErrorMessage(message);
    setIsError(true);
  };

  // CRUD Operations
  const getStudents = async () => {
    try {
      setIsLoading(true);
      const response = await axios.get("http://localhost:5000/students");
      if (response.status === 200) {
        setStudents(response.data);
      }
      if (response.status === 204) {
        setStudents([]);
      }
    } catch (err) {
      showError(err.response?.data?.message || "Error deleting student.");
    } finally {
      setIsLoading(false);
    }
  };

  // Add Student
  const addStudent = async () => {
    if (!Fname || !Lname || !Phone || !Address) {
      showError("Please fill in all fields before adding a student.");
      return;
    }
    const studentToAdd = { Fname, Lname, Phone, Address };
    try {
      setIsLoading(false);
      const response = await axios.post(
        "http://localhost:5000/students",
        studentToAdd
      );
      if (response.status === 201) {
        const newStudent = { ...studentToAdd, id: response.data.id };
        setStudents([...students, newStudent]);
        showSuccess(response.data.message);
      }
      clear();
    } catch (err) {
      showError(err.response?.data?.message || "Error adding student.");
    } finally {
      setIsLoading(false);
    }
  };

  // Update Student
  const updateStudent = async () => {
    if (!Fname || !Lname || !Phone || !Address) {
      showError("Please fill in all fields before updating a student.");
      return;
    }
    if (!id) {
      showError("Please provide an ID for updating a student.");
      return;
    }
    const studentToUpdate = { Fname, Lname, Phone, Address };
    try {
      setIsLoading(false);
      const response = await axios.put(
        "http://localhost:5000/students/" + id,
        studentToUpdate
      );
      if (response.status === 200) {
        setStudents((prev) =>
          prev.map((student) =>
            student.id === id ? { ...studentToUpdate, id } : student
          )
        );
        showSuccess(response.data.message);
      }
      clear();
    } catch (err) {
      showError(err.response?.data?.message || "Error updating student.");
    } finally {
      setIsLoading(false);
    }
  };

  // Delete Student
  const deleteStudent = async (stdID) => {
    try {
      setIsLoading(true);
      const response = await axios.delete(
        "http://localhost:5000/students/" + stdID
      );
      if (response.status === 200) {
        setStudents(students.filter((student) => student.id !== stdID));
        showSuccess(response.data.message);
      }
    } catch (err) {
      showError(err.response?.data?.message || "Error deleting student.");
    } finally {
      setIsLoading(false);
    }
  };

  // Clear form
  const clear = () => {
    setID("");
    setFname("");
    setLname("");
    setPhone("");
    setAddress("");
  };

  // fill students on component load
  useEffect(() => {
    getStudents();
  }, []);

  return (
    <div className="min-h-screen bg-slate-50">
      <div>
        <Navbar />
        <Routes>
          <Route path="/about" Component={About} />
        </Routes>
      </div>
      ;
      <div className="mx-auto max-w-7xl px-4 py-10">
        {/* Header */}
        <div className="mb-8 flex items-start justify-between gap-4">
          <div>
            <h1 className="text-2xl font-bold text-slate-900">Students CRUD</h1>
          </div>

          <button
            className="rounded-lg bg-slate-900 px-4 py-2 text-sm font-semibold text-white hover:bg-slate-800"
            onClick={getStudents}
          >
            Refresh
          </button>
        </div>

        {/* Alerts placeholders */}
        <div className="mb-6 space-y-3">
          {isLoading && (
            <div className="rounded-lg border border-slate-200 bg-white p-3 text-sm text-slate-700">
              Loading...
            </div>
          )}
          {isSuccess && (
            <div className="rounded-lg border border-emerald-200 bg-emerald-50 p-3 text-sm text-emerald-800">
              {successMessage}
            </div>
          )}
          {isError && (
            <div className="rounded-lg border border-rose-200 bg-rose-50 p-3 text-sm text-rose-800">
              {errorMessage}
            </div>
          )}
        </div>

        <div className="grid grid-cols-1 gap-6 lg:grid-cols-3">
          {/* Form */}
          <div className="lg:col-span-1 rounded-2xl border border-slate-200 bg-white p-6 shadow-sm">
            <h2 className="mb-1 text-lg font-semibold text-slate-900">
              Student Form
            </h2>

            <form className="space-y-4">
              <div>
                <label className="mb-1 block text-sm font-medium text-slate-700">
                  ID (only for update)
                </label>
                <input
                  disabled
                  value={id}
                  onChange={(e) => {
                    setID(e.target.value);
                  }}
                  placeholder="Example: 5"
                  className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm focus:border-slate-900 outline-none"
                />
              </div>

              <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
                <input
                  value={Fname}
                  onChange={(e) => {
                    setFname(e.target.value);
                  }}
                  placeholder="First Name"
                  className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm focus:border-slate-900 outline-none"
                />
                <input
                  value={Lname}
                  onChange={(e) => {
                    setLname(e.target.value);
                  }}
                  placeholder="Last Name"
                  className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm focus:border-slate-900 outline-none"
                />
              </div>

              <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
                <input
                  value={Phone}
                  onChange={(e) => {
                    setPhone(e.target.value);
                  }}
                  placeholder="Phone"
                  className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm focus:border-slate-900 outline-none"
                />
                <input
                  value={Address}
                  onChange={(e) => {
                    setAddress(e.target.value);
                  }}
                  placeholder="Address"
                  className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm focus:border-slate-900 outline-none"
                />
              </div>

              <div className="flex flex-wrap gap-2 pt-2">
                <button
                  type="button"
                  className="rounded-lg bg-emerald-600 px-4 py-2 text-sm font-semibold text-white hover:bg-emerald-500"
                  onClick={addStudent}
                >
                  Add
                </button>
                <button
                  type="button"
                  className="rounded-lg bg-blue-600 px-4 py-2 text-sm font-semibold text-white hover:bg-blue-500"
                  onClick={updateStudent}
                >
                  Update
                </button>
                <button
                  type="button"
                  className="rounded-lg border border-slate-300 bg-white px-4 py-2 text-sm font-semibold text-slate-800 hover:bg-slate-50"
                  onClick={clear}
                >
                  Clear
                </button>
              </div>
            </form>
          </div>

          {/* Results */}
          <div className="lg:col-span-2 space-y-6">
            {/* Cards View */}
            <div className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm">
              <div className="mb-4 flex items-center justify-between">
                <h2 className="text-lg font-semibold text-slate-900">
                  Students (Cards)
                </h2>
              </div>

              <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-3">
                {/* Sample Card */}
                {students.map((student, index) => (
                  <div
                    key={student.id}
                    className="rounded-xl border border-slate-200 p-4 hover:shadow-sm"
                  >
                    <div className="mb-2 flex items-center justify-between">
                      <span className="text-xs font-semibold text-slate-500">
                        ID: {student.id}
                      </span>
                      <span className="rounded-full bg-slate-100 px-2 py-0.5 text-xs text-slate-700">
                        Student
                      </span>
                    </div>

                    <h3 className="text-base font-semibold text-slate-900">
                      {student.Fname} {student.Lname}
                    </h3>

                    <p className="mt-1 text-sm text-slate-600">
                      Phone: {student.Phone}
                    </p>
                    <p className="text-sm text-slate-600">
                      Address: {student.Address}
                    </p>

                    <div className="mt-4 flex gap-2">
                      <button
                        className="flex-1 rounded-lg border border-slate-300 bg-white px-3 py-1.5 text-xs font-semibold text-slate-800 hover:bg-slate-50"
                        onClick={() => {
                          setID(student.id);
                          setFname(student.Fname);
                          setLname(student.Lname);
                          setPhone(student.Phone);
                          setAddress(student.Address);
                        }}
                      >
                        Edit
                      </button>
                      <button
                        className="flex-1 rounded-lg bg-rose-600 px-3 py-1.5 text-xs font-semibold text-white hover:bg-rose-500"
                        onClick={() => {
                          deleteStudent(student.id);
                        }}
                      >
                        Delete
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Table View */}
            <div className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm">
              <div className="mb-4">
                <h2 className="text-lg font-semibold text-slate-900">
                  Students (Table)
                </h2>
              </div>

              <div className="overflow-x-auto rounded-lg border border-slate-200">
                <table className="min-w-full divide-y divide-slate-200 text-sm">
                  <thead className="bg-slate-50">
                    <tr className="text-left text-slate-700">
                      <th className="px-4 py-3 font-semibold">ID</th>
                      <th className="px-4 py-3 font-semibold">First</th>
                      <th className="px-4 py-3 font-semibold">Last</th>
                      <th className="px-4 py-3 font-semibold">Phone</th>
                      <th className="px-4 py-3 font-semibold">Address</th>
                      <th className="px-4 py-3 font-semibold">Actions</th>
                    </tr>
                  </thead>

                  <tbody className="divide-y divide-slate-200 bg-white">
                    {students.map((student, index) => (
                      <tr key={student.id} className="hover:bg-slate-50">
                        <td className="px-4 py-3">{student.id}</td>
                        <td className="px-4 py-3">{student.Fname}</td>
                        <td className="px-4 py-3">{student.Lname}</td>
                        <td className="px-4 py-3">{student.Phone}</td>
                        <td className="px-4 py-3">{student.Address}</td>
                        <td className="px-4 py-3">
                          <div className="flex gap-2">
                            <button
                              className="rounded-lg border border-slate-300 bg-white px-3 py-1.5 text-xs font-semibold hover:bg-slate-50"
                              onClick={() => {
                                setID(student.id);
                                setFname(student.Fname);
                                setLname(student.Lname);
                                setPhone(student.Phone);
                                setAddress(student.Address);
                              }}
                            >
                              Edit
                            </button>
                            <button
                              className="rounded-lg bg-rose-600 px-3 py-1.5 text-xs font-semibold text-white hover:bg-rose-500"
                              onClick={() => {
                                deleteStudent(student.id);
                              }}
                            >
                              Delete
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))}

                    <tr className="hidden">
                      <td colSpan={6} className="px-4 py-4 text-slate-600">
                        No students loaded yet.
                      </td>
                    </tr>
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
export default App;
